"use client";

import { useActionState, useState, type FormEvent } from "react";
import { validateContact, type ContactErrors } from "@/lib/contact";
import { sendMessage, type ContactState } from "./actions";

const initialState: ContactState = {
  values: { name: "", email: "", message: "" },
  errors: {},
  success: null,
};

export function ContactForm() {
  const [state, formAction, pending] = useActionState(
    sendMessage,
    initialState,
  );
  const [clientErrors, setClientErrors] = useState<ContactErrors | null>(null);
  const errors = clientErrors ?? state.errors;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    const data = new FormData(event.currentTarget);
    const found = validateContact({
      name: String(data.get("name") ?? ""),
      email: String(data.get("email") ?? ""),
      message: String(data.get("message") ?? ""),
    });
    if (Object.keys(found).length > 0) {
      // Invalid: show the errors and send nothing to the server.
      event.preventDefault();
      setClientErrors(found);
    } else {
      setClientErrors(null);
    }
  }

  return (
    <>
      {state.success && !clientErrors && (
        <p className="success" role="status">
          {state.success}
        </p>
      )}
      <form
        method="post"
        action={formAction}
        onSubmit={handleSubmit}
        noValidate
      >
        <div className="field">
          <label htmlFor="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            defaultValue={state.values.name}
            aria-invalid={errors.name ? true : undefined}
            aria-describedby={errors.name ? "contact-name-error" : undefined}
          />
          {errors.name && (
            <p id="contact-name-error" className="error">
              {errors.name}
            </p>
          )}
        </div>
        <div className="field">
          <label htmlFor="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            defaultValue={state.values.email}
            aria-invalid={errors.email ? true : undefined}
            aria-describedby={errors.email ? "contact-email-error" : undefined}
          />
          {errors.email && (
            <p id="contact-email-error" className="error">
              {errors.email}
            </p>
          )}
        </div>
        <div className="field">
          <label htmlFor="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            rows={6}
            defaultValue={state.values.message}
            aria-invalid={errors.message ? true : undefined}
            aria-describedby={
              errors.message ? "contact-message-error" : undefined
            }
          />
          {errors.message && (
            <p id="contact-message-error" className="error">
              {errors.message}
            </p>
          )}
        </div>
        <button type="submit" disabled={pending}>
          Send
        </button>
      </form>
    </>
  );
}
