import { existsSync } from "node:fs";
import path from "node:path";
import { NextResponse, type NextRequest } from "next/server";

export const config = {
  matcher: "/books/:slug",
};

const BOOKS_DIR = path.join(process.cwd(), "content", "books");

/**
 * Unknown book slugs would otherwise be served from the route's App Shell,
 * which streams with a 200 status. Rewrite them to a path that matches no
 * page so they get the 404 page with a real 404 status.
 */
export function proxy(request: NextRequest) {
  const slug = decodeURIComponent(request.nextUrl.pathname.split("/")[2] ?? "");
  const isBook =
    /^[\w-]+$/.test(slug) && existsSync(path.join(BOOKS_DIR, `${slug}.md`));
  if (!isBook) {
    return NextResponse.rewrite(new URL("/_book-not-found", request.url));
  }
}
